package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.service.CartService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/cart") public class CartController {private final CartService s;public CartController(CartService s){this.s=s;} @GetMapping public CartResponse get(Authentication a){return s.get(a);} @PostMapping("/items") public CartResponse add(Authentication a,@Valid @RequestBody CartItemRequest r){return s.add(a,r);} @DeleteMapping("/items/{productId}") public void remove(Authentication a,@PathVariable UUID productId){s.remove(a,productId);}}